import SwiftUI

// MARK: - Sheet data (generated by Textures/topo/make.py into TopoData.swift)

struct TopoLabel { var x: CGFloat; var y: CGFloat; var angle: CGFloat; var text: String }
struct TopoSpot { var x: CGFloat; var y: CGFloat; var elevation: Int }

struct TopoSheetData {
    var width: CGFloat
    var height: CGFloat
    var texture: String
    var labels: [TopoLabel]
    var spots: [TopoSpot]
    var zones: [CGRect]
    var trees: String
    var lines: String
    var profile: [CGFloat] = []
    var profileLow = 0
    var profileHigh = 0
}

/// One decoded map sheet: the linework grouped into paths by kind, ready for a Canvas.
struct TopoSheet {
    let size: CGSize
    let texture: String
    let labels: [TopoLabel]
    let spots: [TopoSpot]
    let zones: [CGRect]
    let trees: [CGPoint]
    let profile: [CGFloat]
    let profileRange: (low: Int, high: Int)
    var contours = Path()
    var index = Path()
    var shore = Path()
    var lining: [Path] = Array(repeating: Path(), count: 8)
    var streams: [[CGPoint]] = []
    var woodEdge = Path()

    init(_ d: TopoSheetData) {
        size = CGSize(width: d.width, height: d.height)
        texture = d.texture
        labels = d.labels
        spots = d.spots
        zones = d.zones
        profile = d.profile
        profileRange = (d.profileLow, d.profileHigh)
        let t = Self.int16s(d.trees)
        trees = stride(from: 0, to: t.count - 1, by: 2).map { CGPoint(x: CGFloat(t[$0]) / 10, y: CGFloat(t[$0 + 1]) / 10) }
        let v = Self.int16s(d.lines)
        var i = 0
        while i + 1 < v.count {
            let kind = Int(v[i]), n = Int(v[i + 1])
            i += 2
            guard i + 2 * n <= v.count else { break }
            var pts: [CGPoint] = []
            pts.reserveCapacity(n)
            for k in 0..<n { pts.append(CGPoint(x: CGFloat(v[i + 2 * k]) / 10, y: CGFloat(v[i + 2 * k + 1]) / 10)) }
            i += 2 * n
            switch kind {
            case 0: Self.addSmooth(&contours, pts)
            case 1: Self.addSmooth(&index, pts)
            case 2: Self.addSmooth(&shore, pts)
            case 3...8: Self.addSmooth(&lining[kind - 3], pts)
            case 9: streams.append(pts)
            case 10: Self.addSmooth(&woodEdge, pts)
            default: break
            }
        }
    }

    static func int16s(_ b64: String) -> [Int16] {
        guard let data = Data(base64Encoded: b64, options: .ignoreUnknownCharacters) else { return [] }
        let b = [UInt8](data)
        return stride(from: 0, to: b.count - 1, by: 2).map { Int16(bitPattern: UInt16(b[$0]) | UInt16(b[$0 + 1]) << 8) }
    }

    /// Quadratic curves through the midpoints, so the generated polylines read as drawn contours.
    static func addSmooth(_ p: inout Path, _ pts: [CGPoint], continuing: Bool = false) {
        guard pts.count > 2 else {
            if pts.count == 2 {
                if continuing { p.addLine(to: pts[0]) } else { p.move(to: pts[0]) }
                p.addLine(to: pts[1])
            }
            return
        }
        if continuing { p.addLine(to: pts[0]) } else { p.move(to: pts[0]) }
        for i in 1..<(pts.count - 1) {
            let m = CGPoint(x: (pts[i].x + pts[i + 1].x) / 2, y: (pts[i].y + pts[i + 1].y) / 2)
            p.addQuadCurve(to: m, control: pts[i])
        }
        p.addLine(to: pts[pts.count - 1])
    }

    @MainActor static let dayLarge = TopoSheet(TopoData.dayLarge)
    @MainActor static let dayMedium = TopoSheet(TopoData.dayMedium)
    @MainActor static let daySmall = TopoSheet(TopoData.daySmall)
    @MainActor static let quoteLarge = TopoSheet(TopoData.quoteLarge)
    @MainActor static let quoteMedium = TopoSheet(TopoData.quoteMedium)
    @MainActor static let quoteSmall = TopoSheet(TopoData.quoteSmall)
}

// MARK: - The map sheet: paper and relief raster, linework, survey grid, neatline

struct MapSheet: View {
    let sheet: TopoSheet
    var grid: CGFloat = 58
    var gridOrigin = CGPoint(x: 31, y: 37)
    var easting = 412
    var northing = 3771
    /// Small print in the bottom margin, as on a survey sheet's collar.
    var marginNote: String? = nil

    var body: some View {
        ZStack(alignment: .topLeading) {
            Mock.texture(sheet.texture).resizable().interpolation(.high)
            MapLinework(sheet: sheet).mask(ZoneFade(zones: sheet.zones, keep: 0.68))
            SurveyGrid(size: sheet.size, step: grid, origin: gridOrigin, easting: easting, northing: northing)
            Neatline()
            if let note = marginNote {
                Text(note).font(TopoFont.menlo(5)).tracking(0.6).foregroundColor(TopoInk.inkSoft)
                    .padding(.horizontal, 3)
                    .background(TopoInk.paperLight.opacity(0.9))
                    .frame(width: sheet.size.width, height: 10)
                    .offset(y: sheet.size.height - 10.6)
            }
        }
        .frame(width: sheet.size.width, height: sheet.size.height)
    }
}

/// Lowers the linework under text areas, as a map's knockouts do, with soft edges.
struct ZoneFade: View {
    let zones: [CGRect]
    var keep: Double

    var body: some View {
        Canvas { ctx, size in
            ctx.fill(Path(CGRect(origin: .zero, size: size)), with: .color(.white))
            var holes = Path()
            for z in zones { holes.addRoundedRect(in: z.insetBy(dx: 2, dy: 2), cornerSize: CGSize(width: 8, height: 8)) }
            ctx.blendMode = .destinationOut
            ctx.addFilter(.blur(radius: 5))
            ctx.fill(holes, with: .color(.white.opacity(1 - keep)))
        }
    }
}

struct MapLinework: View {
    let sheet: TopoSheet

    var body: some View {
        Canvas { ctx, _ in
            drawWater(&ctx)
            ctx.stroke(sheet.woodEdge, with: .color(TopoInk.forest.opacity(0.75)),
                       style: StrokeStyle(lineWidth: 0.55, lineCap: .round, dash: [0.1, 1.5]))
            drawContours(&ctx)
            drawStreams(&ctx)
            drawTrees(&ctx)
            drawLabels(&ctx)
            drawSpots(&ctx)
        }
    }

    private func drawWater(_ ctx: inout GraphicsContext) {
        for (i, p) in sheet.lining.enumerated() {
            ctx.stroke(p, with: .color(TopoInk.water.opacity(0.62 - Double(i) * 0.06)), lineWidth: 0.42)
        }
        ctx.stroke(sheet.shore, with: .color(TopoInk.waterInk), lineWidth: 0.95)
    }

    private func labelText(_ s: String) -> Text {
        Text(s).font(TopoFont.futura(6.4)).foregroundColor(TopoInk.contourIndex)
    }

    private func drawContours(_ ctx: inout GraphicsContext) {
        var gaps = Path()
        for l in sheet.labels {
            let sz = ctx.resolve(labelText(l.text)).measure(in: CGSize(width: 80, height: 20))
            let r = CGRect(x: -sz.width / 2 - 1.6, y: -3.2, width: sz.width + 3.2, height: 6.4)
            let t = CGAffineTransform(translationX: l.x, y: l.y).rotated(by: l.angle * .pi / 180)
            gaps.addPath(Path(r), transform: t)
        }
        var c = ctx
        c.clip(to: gaps, options: .inverse)
        c.stroke(sheet.contours, with: .color(TopoInk.contour.opacity(0.62)), lineWidth: 0.42)
        c.stroke(sheet.index, with: .color(TopoInk.contourIndex.opacity(0.9)), lineWidth: 0.95)
    }

    private func drawStreams(_ ctx: inout GraphicsContext) {
        for s in sheet.streams where s.count > 4 {
            // taper: thin at the spring, fuller toward the lake
            let n = s.count
            let parts = 4
            for k in 0..<parts {
                let a = k * (n - 1) / parts, b = min(n - 1, (k + 1) * (n - 1) / parts + 1)
                var p = Path()
                TopoSheet.addSmooth(&p, Array(s[a...b]))
                ctx.stroke(p, with: .color(TopoInk.waterInk.opacity(0.95)),
                           style: StrokeStyle(lineWidth: 0.5 + CGFloat(k) * 0.28, lineCap: .round, lineJoin: .round))
            }
        }
    }

    private func drawTrees(_ ctx: inout GraphicsContext) {
        var crowns = Path(), trunks = Path()
        for t in sheet.trees {
            crowns.addEllipse(in: CGRect(x: t.x - 1.5, y: t.y - 2.3, width: 3.0, height: 2.8))
            trunks.move(to: CGPoint(x: t.x, y: t.y + 0.5))
            trunks.addLine(to: CGPoint(x: t.x, y: t.y + 1.7))
        }
        ctx.fill(crowns, with: .color(Color(hex: 0xA9C08A).opacity(0.85)))
        ctx.stroke(crowns, with: .color(TopoInk.forest.opacity(0.85)), lineWidth: 0.5)
        ctx.stroke(trunks, with: .color(TopoInk.forest.opacity(0.85)), lineWidth: 0.5)
    }

    private func drawLabels(_ ctx: inout GraphicsContext) {
        for l in sheet.labels {
            var c = ctx
            c.translateBy(x: l.x, y: l.y)
            c.rotate(by: .degrees(Double(l.angle)))
            c.draw(c.resolve(labelText(l.text)), at: .zero, anchor: .center)
        }
    }

    private func drawSpots(_ ctx: inout GraphicsContext) {
        for (i, s) in sheet.spots.enumerated() {
            if i == 0 {
                var tri = Path()
                tri.move(to: CGPoint(x: s.x, y: s.y - 3.2))
                tri.addLine(to: CGPoint(x: s.x + 2.9, y: s.y + 1.8))
                tri.addLine(to: CGPoint(x: s.x - 2.9, y: s.y + 1.8))
                tri.closeSubpath()
                ctx.fill(tri, with: .color(TopoInk.paperLight))
                ctx.stroke(tri, with: .color(TopoInk.ink), lineWidth: 0.7)
                ctx.fill(Path(ellipseIn: CGRect(x: s.x - 0.7, y: s.y - 0.3, width: 1.4, height: 1.4)), with: .color(TopoInk.ink))
            } else {
                var x = Path()
                x.move(to: CGPoint(x: s.x - 1.6, y: s.y - 1.6)); x.addLine(to: CGPoint(x: s.x + 1.6, y: s.y + 1.6))
                x.move(to: CGPoint(x: s.x + 1.6, y: s.y - 1.6)); x.addLine(to: CGPoint(x: s.x - 1.6, y: s.y + 1.6))
                ctx.stroke(x, with: .color(TopoInk.ink), lineWidth: 0.7)
            }
            let t = Text(verbatim: "\(s.elevation)").font(TopoFont.futuraItalic(6.8)).foregroundColor(TopoInk.ink)
            ctx.draw(ctx.resolve(t), at: CGPoint(x: s.x + 4.5, y: s.y + 0.5), anchor: .leading)
        }
    }
}

// MARK: - Survey grid with crosses and margin coordinates

struct SurveyGrid: View {
    let size: CGSize
    let step: CGFloat
    let origin: CGPoint
    let easting: Int
    let northing: Int

    private var xs: [CGFloat] { stride(from: origin.x, to: size.width - 14, by: step).filter { $0 > 14 } }
    private var ys: [CGFloat] { stride(from: origin.y, to: size.height - 14, by: step).filter { $0 > 14 } }

    var body: some View {
        Canvas { ctx, _ in
            var lines = Path(), crosses = Path(), ticks = Path()
            for x in xs {
                lines.move(to: CGPoint(x: x, y: 8)); lines.addLine(to: CGPoint(x: x, y: size.height - 8))
                ticks.move(to: CGPoint(x: x, y: 7.7)); ticks.addLine(to: CGPoint(x: x, y: 12))
                ticks.move(to: CGPoint(x: x, y: size.height - 7.7)); ticks.addLine(to: CGPoint(x: x, y: size.height - 12))
            }
            for y in ys {
                lines.move(to: CGPoint(x: 8, y: y)); lines.addLine(to: CGPoint(x: size.width - 8, y: y))
                ticks.move(to: CGPoint(x: 7.7, y: y)); ticks.addLine(to: CGPoint(x: 12, y: y))
                ticks.move(to: CGPoint(x: size.width - 7.7, y: y)); ticks.addLine(to: CGPoint(x: size.width - 12, y: y))
            }
            for x in xs { for y in ys {
                crosses.move(to: CGPoint(x: x - 3.5, y: y)); crosses.addLine(to: CGPoint(x: x + 3.5, y: y))
                crosses.move(to: CGPoint(x: x, y: y - 3.5)); crosses.addLine(to: CGPoint(x: x, y: y + 3.5))
            } }
            ctx.stroke(lines, with: .color(TopoInk.grid.opacity(0.22)), lineWidth: 0.4)
            ctx.stroke(crosses, with: .color(TopoInk.grid.opacity(0.75)), lineWidth: 0.6)
            ctx.stroke(ticks, with: .color(TopoInk.ink.opacity(0.85)), lineWidth: 0.6)
            drawCoordinates(&ctx)
        }
        .allowsHitTesting(false)
    }

    private func coord(_ s: String) -> Text {
        Text(s).font(TopoFont.menlo(5.2)).foregroundColor(TopoInk.inkSoft)
    }

    private func drawCoordinates(_ ctx: inout GraphicsContext) {
        for (i, x) in xs.enumerated() where x > 26 && x < size.width - 26 {
            ctx.draw(ctx.resolve(coord("\(easting + i)")), at: CGPoint(x: x + 1.4, y: 9.2), anchor: .topLeading)
        }
        for (i, y) in ys.enumerated() where y > 26 && y < size.height - 26 {
            var c = ctx
            c.translateBy(x: 9.2, y: y - 1.4)
            c.rotate(by: .degrees(-90))
            c.draw(c.resolve(coord("\(northing - i)")), at: .zero, anchor: .topLeading)
        }
    }
}

/// The sheet's border: an outer rule, a zebra graduated band, and an inner rule, following the widget's corners.
struct Neatline: View {
    var body: some View {
        ZStack {
            border(3.5).stroke(TopoInk.ink.opacity(0.85), lineWidth: 0.7)
            border(5.6).stroke(TopoInk.paperLight, lineWidth: 2.6)
            border(5.6).stroke(TopoInk.ink.opacity(0.88), style: StrokeStyle(lineWidth: 2.6, dash: [7, 7]))
            border(7.7).stroke(TopoInk.ink.opacity(0.85), lineWidth: 0.5)
        }
        .allowsHitTesting(false)
    }

    private func border(_ inset: CGFloat) -> some Shape {
        RoundedRectangle(cornerRadius: Mock.cornerRadius, style: .continuous).inset(by: inset)
    }
}
